// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

/// @notice Optional per-engine risk hook for account valuation.
/// @dev Engines can contribute:
///      - `pnlUSDWad`: signed mark-to-market PnL (USD, 1e18)
///      - `maintUSDWad`: additional maintenance margin requirement (USD, 1e18)
interface IAccountRiskModule {
    function riskContribution(
        address pm,
        address user
    )
        external
        view
        returns (int256 pnlUSDWad, uint256 maintUSDWad);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

/// @dev All values are USD-WAD (1e18 = $1).
struct AccountSnapshot {
    /// max(coll - debt + enginePnL, 0)
    uint256 equityUSDWad;
    /// Maintenance requirement: sum of (assetValue * mmBps) for collateral + debt, plus engine maintenance.
    uint256 maintUSDWad;
    /// collUSDWad + max(enginePnL, 0). Includes positive engine PnL as "effective" collateral
    /// for UI display and repay-cap math (computeMinRepayment). NOT suitable for seize-eligibility
    /// checks because engine PnL is not seizable collateral.
    uint256 pnlAdjCollUSDWad;
    /// Pure on-chain collateral value: sum of (avail * oraclePrice) for collateral-flagged assets.
    /// Excludes engine PnL. A zero-priced asset contributes zero. Use this for seize-eligibility
    /// checks (e.g. insolvency exception: collUSDWad == 0 means nothing left to seize).
    uint256 collUSDWad;
    /// Pure on-chain debt value: sum of (principalNow * oraclePrice) for debt assets.
    /// A zero-priced debt asset contributes zero (undervalues real debt).
    uint256 debtUSDWad;
    /// Aggregate unrealized PnL from engine risk modules (signed). Not derivable from other
    /// fields when negative due to the equity floor at zero. Provided for off-chain consumers
    /// (portfolio UI, debugging). Verifiable: equity == max(coll - debt + enginePnL, 0).
    int256 enginePnLUSDWad;
}

interface IAccountValuesLens {
    function accountValues(address pm, address user) external view returns (AccountSnapshot memory);
    function previewBorrowIndexWad(
        address pmAddr,
        address asset
    )
        external
        view
        returns (uint256 idxNow);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

interface IConfigRegistry {
    struct AssetCfg {
        address irm;
        uint16 mmBps; /// @notice Maintenance margin rate per asset (bps). E.g. 125 => 1.25% maintenance.
        bool enabled;
        address ftYieldWrapper;
        bool borrowable;
        bool collateral;
    }

    event GuardianChanged(address indexed g);
    event AssetSet(address indexed asset, AssetCfg cfg);
    event OracleSet(address indexed router);
    event MarginHFTargetSet(uint16 bps);
    event MarginHFSafeSet(uint16 bps);
    event MarginMinEquitySet(uint256 minEquityUSDWad);
    event MMChanged(address indexed asset, uint16 newMM);
    event OracleChanged(address indexed next);
    event BorrowableChanged(address indexed asset, bool borrowable);
    event CollateralChanged(address indexed asset, bool collateral);

    function getAssetCfg(address asset) external view returns (AssetCfg memory);
    function oracleRouter() external view returns (address);
    function marginHfTargetBps() external view returns (uint16);
    function marginHfSafeBps() external view returns (uint16);
    function marginMinEquityUSDWad() external view returns (uint256);
    function dnmmStrategies(address strategy) external view returns (bool);
    function setDNMMStrategy(address strategy, bool ok) external;
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

interface IIRM {
    /// @notice Return borrow APR (WAD, 1e18 = 100%) for `asset` at utilization `utilWad` (0..1e18)
    function borrowAPR(address asset, uint256 utilWad) external view returns (uint256 aprWad);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

import {IConfigRegistry} from "./IConfigRegistry.sol";
import {IAccountValuesLens} from "./IAccountValuesLens.sol";

// Minimal view interface into PositionsManager used by the lens
interface IPMViews {
    function debtShares(address user, address asset) external view returns (uint256 shares);
    function totalDebtShares(address asset) external view returns (uint256);
    function config() external view returns (IConfigRegistry);
    function engines(address m) external view returns (bool);
    function valuesLens() external view returns (IAccountValuesLens);
    function withdrawPaused(address asset) external view returns (bool);
    function depositPaused(address asset) external view returns (bool);
    function borrowPaused(address asset) external view returns (bool);
    function supplyCap(address asset) external view returns (uint256);
    function borrowCap(address asset) external view returns (uint256);
    function DOMAIN_SEPARATOR() external view returns (bytes32);
    function DOMAIN_CHAIN_ID() external view returns (uint256);
    function admin() external view returns (address);
    function metaModules(address module) external view returns (bool);
    function noncesTyped(address user, bytes32 typehash) external view returns (uint256);
    function engineHeld(address user, address engine, address asset) external view returns (uint256);
    function collateral(
        address user,
        address asset
    )
        external
        view
        returns (
            uint256 avail,
            uint256 hold,
            uint40 lastT,
            uint32 lastSettledEpoch,
            uint256 openSupplyTime
        );
    function epochs(
        address asset,
        uint32 epochId
    )
        external
        view
        returns (
            uint40 t_end,
            uint256 S_end,
            uint256 rateRay,
            uint256 X_end,
            uint256 interest,
            uint256 supplyTime
        );
    function astate(address asset)
        external
        view
        returns (
            uint256 borrowIndexWad,
            uint256 cash,
            uint256 borrows,
            uint256 totalSupplied,
            uint256 reserves,
            uint256 totalSuppliedTime,
            uint40 lastAccrual,
            uint32 epoch
        );
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.30;

import {IPMViews} from "./IPMViews.sol";

interface IPositionsManager is IPMViews {
    /*//////////////////////////////////////////////////////////////
                                ERRORS
    //////////////////////////////////////////////////////////////*/

    error ftPositionManagerOnlyOwner();
    error ftPositionManagerOnlyEngine();
    error ftPositionManagerLensZero();
    error ftPositionManagerHealthFactorBelowTarget();
    error ftPositionManagerHealthFactorNotBelowTarget();
    error ftPositionManagerZeroAdmin();
    error ftPositionManagerZeroAddress();
    error ftPositionManagerAssetNotConfigured();
    error ftPositionManagerAssetDisabled();
    error ftPositionManagerAssetNotBorrowable();
    error ftPositionManagerBorrowRequiresMM();
    error ftPositionManagerSupplyCap();
    error ftPositionManagerInsufficientLiquidity();
    error ftPositionManagerHealthFactor();
    error ftPositionManagerMinEquity();
    error ftPositionManagerNoDebt();
    error ftPositionManagerBorrowPaused();
    error ftPositionManagerDepositPaused();
    error ftPositionManagerWithdrawPaused();
    error ftPositionManagerBorrowCap();
    error ftPositionManagerAmountZero();
    error ftPositionManagerInsufficientCash();
    error ftPositionManagerInsufficientReserves();
    error ftPositionManagerNoSupplierInterest();
    error ftPositionManagerInsufficientEngineDebitAllowance();
    error ftPositionManagerInsufficientBorrowAllowance();
    error ftPositionManagerInsufficientEngineHeld();
    error ftPositionManagerEngineReentrancyLockNotOwner();
    error ftPositionManagerSelfTransfer();
    error ftPositionManagerRepayTooLow();
    error ftPositionManagerDebtShareInvariant();
    error ftPositionManagerDepositTooLow();
    error ftPositionManagerNotInitialized();
    error ftPositionManagerAlreadyInitialized();
    error ftPositionManagerInvalidNonce();
    error ftPositionManagerThirdPartyNewCollateralAsset();

    function initializeAsset(address asset) external;

    // ========= User actions =========
    // Convenience overloads (user == msg.sender)
    function deposit(address asset, uint256 amt) external;
    function withdraw(address asset, uint256 amt) external;
    function borrow(address asset, uint256 amt) external;
    function repay(address asset, uint256 amt) external;
    function approveEngine(address engine, address asset, uint256 debitAllowance) external;
    function approveBorrow(address delegate, address asset, uint256 borrowAllowance) external;

    function withdraw(address user, address asset, uint256 amt, address to) external;
    function borrow(address user, address asset, uint256 amt, address to) external;
    function approveEngine(
        address user,
        address engine,
        address asset,
        uint256 debitAllowance
    )
        external;
    function approveBorrow(
        address user,
        address delegate,
        address asset,
        uint256 borrowAllowance
    )
        external;
    function borrowAllowance(
        address user,
        address delegate,
        address asset
    )
        external
        view
        returns (uint256);

    function engineDebitAllowanceOf(
        address user,
        address engine,
        address asset
    )
        external
        view
        returns (uint256);

    function borrowFlashAndDepositFor(
        address user,
        address borrowAsset,
        uint256 borrowAmount,
        address collateralAsset,
        uint256 minCollateralAmount,
        bytes calldata callbackData
    )
        external;
    function withdrawFlashAndRepayFor(
        address user,
        address collateralAsset,
        uint256 collateralAmount,
        address repayAsset,
        uint256 minRepayAmount,
        bytes calldata callbackData
    )
        external;

    function withdrawFlashAndDepositFor(
        address user,
        address collateralAsset,
        uint256 collateralAmount,
        address depositAsset,
        uint256 minDepositAmount,
        bytes calldata callbackData
    )
        external;
    function useTypedNonce(address user, bytes32 typehash) external returns (uint256 nonce);
    function invalidateTypedNonce(bytes32 typehash, uint256 newNonce) external;

    // ========= Views =========
    function getBalance(
        address user,
        address token
    )
        external
        view
        returns (uint256 avail, uint256 hold);

    function userCollateralAssets(address user) external view returns (address[] memory);
    function userDebtAssets(address user) external view returns (address[] memory);
    function setValuesLens(address lens) external;
    function settleEpoch(address asset, uint256 interest) external;
    function setCaps(address asset, uint256 supplyCap_, uint256 borrowCap_) external;
    function setDepositPaused(address asset, bool paused) external;
    function setWithdrawPaused(address asset, bool paused) external;
    function setBorrowPaused(address asset, bool paused) external;
    function depositFor(address beneficiary, address asset, uint256 amount) external;
    function repayFor(address borrower, address asset, uint256 amount) external;
    function engineTransferAvail(address from, address to, address asset, uint128 amt) external;
    function skim(address asset) external;
    function withdrawReserves(address asset, address to, uint256 amount) external;
    function setEngine(address m, bool ok) external;
    function setTokenizer(address asset, address tokenizer_) external;
    function setAdmin(address _admin) external;
    function FT() external view returns (address);

    /// @notice Engine-only hook to toggle the PositionsManager reentrancy guard.
    ///         Used by external engines that perform flash-style callbacks (e.g., RFQ)
    ///         to block reentrant user actions into PM during the callback window.
    /// @param locked When true, subsequent `nonReentrant` PM entrypoints will revert
    ///               until unlocked (or transaction end, since the guard is transient).
    function setEngineReentrancyLock(bool locked) external;
    function setMetaModule(address module, bool ok) external;
    function setLiquidationModule(address module, bool ok) external;
